using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Reflection.Metadata;using System.Reflection.PortableExecutable;using System.Text.Json;class Program{static void Main(){using var stream=File.OpenRead("/mnt/c/Program Files/Elite Observatory/ObservatoryFramework.dll");using var pe=new PEReader(stream);var metadata=pe.GetMetadataReader();var all=metadata.TypeDefinitions.ToList();var types=new HashSet<TypeDefinitionHandle>(all.Where(h=>metadata.GetString(metadata.GetTypeDefinition(h).Name)=="JournalBase"));bool changed=true;while(changed){changed=false;foreach(var handle in all){var definition=metadata.GetTypeDefinition(handle);if(definition.BaseType.Kind==HandleKind.TypeDefinition&&types.Contains((TypeDefinitionHandle)definition.BaseType))changed|=types.Add(handle);}}Console.Write(JsonSerializer.Serialize(new{version=metadata.GetAssemblyDefinition().Version.ToString(),journalTypes=types.Select(h=>metadata.GetString(metadata.GetTypeDefinition(h).Name)).OrderBy(n=>n).ToArray(),journalTypeNames=types.OrderBy(h=>metadata.GetString(metadata.GetTypeDefinition(h).Name)).ToDictionary(h=>metadata.GetString(metadata.GetTypeDefinition(h).Name),h=>{var t=metadata.GetTypeDefinition(h);return metadata.GetString(t.Namespace)+"."+metadata.GetString(t.Name);})}));}}